-- ── story 6-1a: secure sessions ───────────────────────────────────────────
-- Generated by drizzle-kit (the three tables, the device and user columns,
-- the indexes) and hand-amended below the marker: the pre-flight over live
-- user statuses, the CHECKs (the first `users.status` CHECK ever), RLS on
-- `sessions` and the post-migration probe (drizzle-kit is blind to all of
-- them; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: `sessions` (tenant-scoped, RLS), `signin_attempts` and
-- `auth_rate_limits` (no tenant data — a digest, an address, counters — so
-- no tenant_id and no RLS), `devices.failed_badge_ins` / `badge_locked_until`
-- and `users.status_before_deactivation`. No data is rewritten: the only data
-- statement is the read-only pre-flight below. No foreign keys
-- (IMPLEMENTATION-GUIDE §3).
--
-- ── pre-flight: every live user status must be in the new vocabulary ──────
-- `users.status` has had no CHECK until now (app-layer `USER_STATUSES` only).
-- List every offending row at once so an operator fixes them in one pass.
DO $$
DECLARE
	offenders text;
BEGIN
	SELECT string_agg(format('%s (%s): %L', id, email, status), '; ' ORDER BY id)
	INTO offenders
	FROM "users"
	WHERE status IS NULL OR status NOT IN ('invited', 'active', 'deactivated');
	IF offenders IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0074: users with a status outside (invited, active, deactivated) — fix them first: %', offenders;
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "auth_rate_limits" (
	"bucket" text PRIMARY KEY NOT NULL,
	"window_start" timestamp with time zone DEFAULT now() NOT NULL,
	"count" integer DEFAULT 0 NOT NULL
);
--> statement-breakpoint
CREATE TABLE "sessions" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"device_id" uuid,
	"client_id" uuid,
	"refresh_hash" text,
	"prev_refresh_hash" text,
	"rotated_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_used_at" timestamp with time zone DEFAULT now() NOT NULL,
	"idle_expires_at" timestamp with time zone NOT NULL,
	"absolute_expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"revoked_reason" text
);
--> statement-breakpoint
CREATE TABLE "signin_attempts" (
	"email_hash" text NOT NULL,
	"ip" text NOT NULL,
	"failures" integer DEFAULT 0 NOT NULL,
	"locked_until" timestamp with time zone,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "signin_attempts_email_hash_ip_pk" PRIMARY KEY("email_hash","ip")
);
--> statement-breakpoint
ALTER TABLE "devices" ADD COLUMN "failed_badge_ins" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "devices" ADD COLUMN "badge_locked_until" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "status_before_deactivation" text;--> statement-breakpoint
CREATE UNIQUE INDEX "sessions_refresh_hash_unique" ON "sessions" USING btree ("refresh_hash");--> statement-breakpoint
CREATE INDEX "sessions_user_live_idx" ON "sessions" USING btree ("user_id") WHERE revoked_at is null;--> statement-breakpoint
CREATE INDEX "sessions_tenant_client_idx" ON "sessions" USING btree ("tenant_id","client_id");--> statement-breakpoint
CREATE INDEX "sessions_device_idx" ON "sessions" USING btree ("device_id");
--> statement-breakpoint
-- ── hand-amended: the controlled vocabularies (IMPLEMENTATION-GUIDE §4) ────
-- Pinned against `USER_STATUSES` (schema.ts), `SESSION_KINDS` and
-- `SESSION_REVOKE_REASONS` (modules/tenancy/sessions.ts) by
-- test/sessions.spec.ts. Nullable columns say IS NULL / IS NOT NULL first.
ALTER TABLE "users" ADD CONSTRAINT "users_status_check" CHECK ("status" IN ('invited', 'active', 'deactivated'));--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_status_before_deactivation_check" CHECK (
	("status" = 'deactivated') = ("status_before_deactivation" IS NOT NULL)
	AND ("status_before_deactivation" IS NULL OR "status_before_deactivation" IN ('invited', 'active'))
);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_kind_check" CHECK ("kind" IN ('web', 'portal', 'badge'));--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_revoked_reason_check" CHECK (
	("revoked_at" IS NULL) = ("revoked_reason" IS NULL)
	AND ("revoked_reason" IS NULL OR "revoked_reason" IN (
		'signed-out', 'deactivated', 'role-changed', 'client-suspended', 'refresh-reuse', 'released', 'device-revoked'
	))
);--> statement-breakpoint
-- A badge session names its device and carries no refresh token; a portal
-- session names its client; a web session names neither.
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_kind_shape_check" CHECK (
	("kind" <> 'badge' OR ("device_id" IS NOT NULL AND "client_id" IS NULL AND "refresh_hash" IS NULL AND "prev_refresh_hash" IS NULL))
	AND ("kind" <> 'portal' OR ("client_id" IS NOT NULL AND "device_id" IS NULL))
	AND ("kind" <> 'web' OR ("client_id" IS NULL AND "device_id" IS NULL))
);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_window_check" CHECK ("idle_expires_at" <= "absolute_expires_at");--> statement-breakpoint
ALTER TABLE "signin_attempts" ADD CONSTRAINT "signin_attempts_failures_check" CHECK ("failures" >= 0);--> statement-breakpoint
ALTER TABLE "devices" ADD CONSTRAINT "devices_failed_badge_ins_check" CHECK ("failed_badge_ins" >= 0);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy ─────────────────────────
ALTER TABLE "sessions" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "sessions_tenant_isolation" ON "sessions"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0070 model) ────────────────────
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes, rolled back by a sentinel.
	BEGIN
		INSERT INTO "sessions" ("id","tenant_id","user_id","kind","device_id","client_id","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
		VALUES (gen_random_uuid(), t, u, 'web', NULL, NULL, 'h1', now(), now() + interval '12 hours', NULL, NULL),
		       (gen_random_uuid(), t, u, 'portal', NULL, gen_random_uuid(), 'h2', now(), now() + interval '7 days', now(), 'client-suspended'),
		       (gen_random_uuid(), t, u, 'badge', gen_random_uuid(), NULL, NULL, now(), now(), now(), 'released'),
		       (gen_random_uuid(), t, u, 'badge', gen_random_uuid(), NULL, NULL, now(), now(), now(), 'device-revoked');
		INSERT INTO "users" ("id","tenant_id","email","password_hash","role","status","status_before_deactivation")
		VALUES (gen_random_uuid(), t, 'probe-0074-a@example.invalid', 'x', 'operator', 'deactivated', 'invited'),
		       (gen_random_uuid(), t, 'probe-0074-b@example.invalid', 'x', 'operator', 'active', NULL);
		RAISE EXCEPTION USING ERRCODE = 'P0074', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0074: an accepted shape was refused.';
		WHEN SQLSTATE 'P0074' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown user status', 'deactivated without a prior status', 'active with a prior status',
		'unknown session kind', 'revoked without a reason', 'unknown revoke reason',
		'badge without a device', 'portal without a client', 'web with a client',
		'idle past absolute', 'negative failures', 'negative badge failures'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown user status' THEN 'users_status_check'
			WHEN 'deactivated without a prior status' THEN 'users_status_before_deactivation_check'
			WHEN 'active with a prior status' THEN 'users_status_before_deactivation_check'
			WHEN 'unknown session kind' THEN 'sessions_kind_check'
			WHEN 'revoked without a reason' THEN 'sessions_revoked_reason_check'
			WHEN 'unknown revoke reason' THEN 'sessions_revoked_reason_check'
			WHEN 'idle past absolute' THEN 'sessions_window_check'
			WHEN 'negative failures' THEN 'signin_attempts_failures_check'
			WHEN 'negative badge failures' THEN 'devices_failed_badge_ins_check'
			ELSE 'sessions_kind_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown user status' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","status") VALUES (gen_random_uuid(), t, 'p1-0074@example.invalid', 'x', 'gone');
				WHEN 'deactivated without a prior status' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","status") VALUES (gen_random_uuid(), t, 'p2-0074@example.invalid', 'x', 'deactivated');
				WHEN 'active with a prior status' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","status","status_before_deactivation") VALUES (gen_random_uuid(), t, 'p3-0074@example.invalid', 'x', 'active', 'invited');
				WHEN 'unknown session kind' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at") VALUES (gen_random_uuid(), t, u, 'device', now(), now());
				WHEN 'revoked without a reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at","revoked_at") VALUES (gen_random_uuid(), t, u, 'web', now(), now(), now());
				WHEN 'unknown revoke reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason") VALUES (gen_random_uuid(), t, u, 'web', now(), now(), now(), 'idle');
				WHEN 'badge without a device' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at") VALUES (gen_random_uuid(), t, u, 'badge', now(), now());
				WHEN 'portal without a client' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at") VALUES (gen_random_uuid(), t, u, 'portal', now(), now());
				WHEN 'web with a client' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","client_id","idle_expires_at","absolute_expires_at") VALUES (gen_random_uuid(), t, u, 'web', gen_random_uuid(), now(), now());
				WHEN 'idle past absolute' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at") VALUES (gen_random_uuid(), t, u, 'web', now() + interval '1 hour', now());
				WHEN 'negative failures' THEN
					INSERT INTO "signin_attempts" ("email_hash","ip","failures") VALUES ('probe', '127.0.0.1', -1);
				WHEN 'negative badge failures' THEN
					INSERT INTO "devices" ("id","tenant_id","failed_badge_ins") VALUES (gen_random_uuid(), t, -1);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0074: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
END $$;
